# ============================================================
# 主流程
# ============================================================
for p in sorted(ROOT.rglob('*.md')):
    text = p.read_text(encoding='utf-8', errors='ignore')

    # ---- 1. 逐行扫描规则 ----
    for i, line in enumerate(text.splitlines(), 1):
        s = line.strip()
        if not s:
            continue
        for rule_name, pattern, desc in RULES:
            match = re.search(pattern, s)
            if match:
                ISSUES.append(
                    f"{p}:{i}: [{rule_name}] {desc}（命中：'{match.group(0)}'）"
                )

    # ---- 2. 对话标签合计检查：他说 / 她说 / 它说 合计 >= 3 次 ----
    tag_count = len(re.findall(r'(?:他|她|它)(?:说|道)', text))
    if tag_count >= 3:
        ISSUES.append(
            f"{p}: [对话标签过多] “他说/她说/它说”合计 {tag_count} 次"
            f"（阈值 3），建议改用动作、神态或直接引语替代"
        )

    # ---- 3. 连续对话标签交替使用检查 ----
    streak = 0
    max_streak = 0
    for line in text.splitlines():
        if re.match(r'^\s*(他|她|它)(?:说|道)', line.strip()):
            streak += 1
            max_streak = max(max_streak, streak)
        else:
            streak = 0
    if max_streak >= 3:
        ISSUES.append(
            f"{p}: [对话标签连续] 连续 {max_streak} 行以'他说/她说/它说'开头，"
            f"节奏机械，建议打散"
        )

# ============================================================
# 写日志
# ============================================================
LOG_DIR.mkdir(parents=True, exist_ok=True)
report_file = LOG_DIR / '反AI味检测.txt'

now = datetime.datetime.now(CST).strftime('%Y-%m-%d %H:%M:%S CST')
content = f"检查时间: {now}\n----------------------------------------\n"

if ISSUES:
    content += f"共发现 {len(ISSUES)} 处 AI 写作特征：\n\n"
    content += "\n".join(ISSUES)
    print(f"发现 {len(ISSUES)} 处 AI 写作特征")
    with open(os.environ['GITHUB_ENV'], 'a') as f:
        f.write("HAS_AISLOP=1\n")
else:
    content += "未检测到 AI 写作特征"
    print("反 AI 味检测通过")

report_file.write_text(content, encoding='utf-8')